#!/usr/bin/env node
'use strict';
const fs=require('fs'),path=require('path'),crypto=require('crypto');const HERE=__dirname,ROOT=path.resolve(HERE,'../../../..');
const CONTROL=path.join(HERE,'controls.json'),SCORE=path.join(ROOT,'research/rev7-20260909-codex/coverage/occupancy_screen_controls/score.js'),TABLE=path.join(ROOT,'research/rev7-20260909-codex/coverage/occupancy_screen_controls/threshold_table.json');
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');const want={score:'6ff228f71ef8e9441c3ba12418d8b49c7238ff4e66ed0eef0f24471a3573ae27',table:'2d084a536141c8e51045b1fa1052ddfc713e0e5f7a869fd62676cf788dfbb447'};
function generate(){if(sha(fs.readFileSync(SCORE))!==want.score||sha(fs.readFileSync(TABLE))!==want.table)throw Error('scorer pins');const C=JSON.parse(fs.readFileSync(CONTROL));if(C.identity!=='ASTRA'||C.target_evaluated!==false||C.paths.identity.truth_matches!==1||C.paths.reverse.truth_matches!==1||C.paths.reverse_words.truth_matches!==1)throw Error('RA controls');const S=require(SCORE),t=S.loadTable(TABLE),b=Buffer.from(C.plant.bytes_hex,'hex');if(sha(b)!==C.plant.sha256||new Set(b).size!==40)throw Error('plant');const full=S.scoreBytes(b,t),short=S.scoreBytes(b.subarray(0,127),t),long=S.scoreBytes(Buffer.alloc(1093),t);if(full.n!==200||full.D!==40||full.screen_hit!==true||short.status!=='short'||short.screen_hit!==null||long.status!=='out-of-range'||long.screen_hit!==null)throw Error('scorer semantics');return {identity:'ASTRA',target_evaluated:false,status:'synthetic controls complete',ra_controls_sha256:sha(fs.readFileSync(CONTROL)),scorer_sha256:want.score,table_sha256:want.table,full_output:full,unsupported_controls:[short,long]};}
let out=null;for(let i=2;i<process.argv.length;i++){if(process.argv[i]==='--generate')out=process.argv[++i];else throw Error('usage: controls.js [--generate NEW_FILE]');}const got=generate();if(out){if(fs.existsSync(out))throw Error('refusing existing');fs.writeFileSync(out,JSON.stringify(got));}else{const p=path.join(HERE,'scorer_controls.json'),saved=JSON.parse(fs.readFileSync(p));if(JSON.stringify(saved)!==JSON.stringify(got))throw Error('saved ledger mismatch');process.stdout.write(JSON.stringify(got)+'\n');}
